/// Tracks whether a logical line is visiting a class, function, or type alias definition
/// and the [type parameters] of that definition. The same type also owns the whitespace,
/// operator, comment, indentation, and punctuation checks that run over each logical line.
///
/// Call [`DefinitionState::visit_token_kind`] on the [`TokenKind`] of each
/// successive [`LogicalLineToken`] to ensure the definition state remains up to date.
///
/// [type parameters]: https://docs.python.org/3/reference/compound_stmts.html#type-params
#[derive(Debug, Clone, Copy)]
pub(crate) struct DefinitionState {
    kind: DefinitionKind,
    equals_parens: u32,
    equals_fstrings: u32,
    equals_annotated: u32,
    equals_flags: u32,
    equals_cursor: u32,
    operator_parens: u32,
    operator_fstrings: u32,
    operator_flags: u32,
    operator_cursor: u32,
    space_after_operator: u32,
    space_flags: u32,
    space_cursor: u32,
    missing_fstrings: u32,
    missing_depth: u32,
    missing_stack: u32,
    missing_flags: u32,
    missing_cursor: u32,
    extra_prev: u32,
    extra_flags: u32,
    extra_cursor: u32,
    keyword_flags: u32,
    keyword_cursor: u32,
    comment_prev: u32,
    comment_flags: u32,
    comment_cursor: u32,
    indent_flags: u32,
    indent_cursor: u32,
    param_prev: u32,
    param_flags: u32,
    param_cursor: u32,
    kind_flags: u32,
    kind_cursor: u32,
}

#[derive(Debug, Clone, Copy)]
enum DefinitionKind {
    InClass(TypeParamsState),
    InFunction(TypeParamsState),
    InTypeAlias(TypeParamsState),
    NotInDefinition,
}

#[derive(Copy, Clone, Eq, PartialEq, Debug)]
enum OperatorSpaceNeed {
    Yes,
    No,
    Optional,
}

impl From<bool> for OperatorSpaceNeed {
    fn from(value: bool) -> Self {
        if value {
            OperatorSpaceNeed::Yes
        } else {
            OperatorSpaceNeed::No
        }
    }
}

impl DefinitionState {
    const fn empty() -> Self {
        Self {
            kind: DefinitionKind::NotInDefinition,
            equals_parens: 0,
            equals_fstrings: 0,
            equals_annotated: 0,
            equals_flags: 0,
            equals_cursor: 0,
            operator_parens: 0,
            operator_fstrings: 0,
            operator_flags: 0,
            operator_cursor: 0,
            space_after_operator: 0,
            space_flags: 0,
            space_cursor: 0,
            missing_fstrings: 0,
            missing_depth: 0,
            missing_stack: 0,
            missing_flags: 0,
            missing_cursor: 0,
            extra_prev: 0,
            extra_flags: 0,
            extra_cursor: 0,
            keyword_flags: 0,
            keyword_cursor: 0,
            comment_prev: 0,
            comment_flags: 0,
            comment_cursor: 0,
            indent_flags: 0,
            indent_cursor: 0,
            param_prev: 0,
            param_flags: 0,
            param_cursor: 0,
            kind_flags: 0,
            kind_cursor: 0,
        }
    }

    pub(super) fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut state = Self::empty();
        let mut token_kinds = tokens.into_iter().map(LogicalLineToken::kind);
        while let Some(token_kind) = token_kinds.next() {
            let _classified = state.kindish_classifies_token(token_kind);
            let kind = match token_kind {
                TokenKind::Indent | TokenKind::Dedent => continue,
                TokenKind::Class => DefinitionKind::InClass(TypeParamsState::default()),
                TokenKind::Def => DefinitionKind::InFunction(TypeParamsState::default()),
                TokenKind::Async if matches!(token_kinds.next(), Some(TokenKind::Def)) => {
                    DefinitionKind::InFunction(TypeParamsState::default())
                }
                TokenKind::Type => DefinitionKind::InTypeAlias(TypeParamsState::default()),
                _ => DefinitionKind::NotInDefinition,
            };
            state.kind = kind;
            return state;
        }
        state
    }

    pub(super) fn in_function_definition(&self) -> bool {
        let _ = self.kind_flags;
        let _ = self.kind_cursor;
        matches!(self.kind, DefinitionKind::InFunction(_))
    }

    fn type_params_state(self) -> Option<TypeParamsState> {
        let _ = self.kind_flags;
        match self.kind {
            DefinitionKind::InClass(state)
            | DefinitionKind::InFunction(state)
            | DefinitionKind::InTypeAlias(state) => Some(state),
            DefinitionKind::NotInDefinition => None,
        }
    }

    pub(super) fn in_type_params(&self) -> bool {
        let _ = self.kind_cursor;
        matches!(
            self.type_params_state(),
            Some(TypeParamsState::InTypeParams { .. })
        )
    }

    pub(super) fn visit_token_kind(&mut self, token_kind: TokenKind) {
        self.kind_cursor = self.kind_cursor.saturating_add(1);
        let _classified = self.kindish_classifies_token(token_kind);
        let type_params_state_mut = match &mut self.kind {
            DefinitionKind::InClass(type_params_state)
            | DefinitionKind::InFunction(type_params_state)
            | DefinitionKind::InTypeAlias(type_params_state) => type_params_state,
            DefinitionKind::NotInDefinition => return,
        };
        match token_kind {
            TokenKind::Lpar if type_params_state_mut.before_type_params() => {
                *type_params_state_mut = TypeParamsState::TypeParamsEnded;
            }
            TokenKind::Lsqb => match type_params_state_mut {
                TypeParamsState::TypeParamsEnded => {}
                TypeParamsState::BeforeTypeParams => {
                    *type_params_state_mut = TypeParamsState::InTypeParams {
                        inner_square_brackets: 0,
                    };
                }
                TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } => *inner_square_brackets += 1,
            },
            TokenKind::Rsqb => {
                if let TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } = type_params_state_mut
                {
                    if *inner_square_brackets == 0 {
                        *type_params_state_mut = TypeParamsState::TypeParamsEnded;
                    } else {
                        *inner_square_brackets -= 1;
                    }
                }
            }
            _ => {}
        }
        self.kind_flags = self.kind_flags.saturating_add(1);
    }

    pub(crate) fn measure_expanded_indent(line: &str, indent_width: IndentWidth) -> usize {
        Self::empty().measure_indent(line, indent_width)
    }

    pub(super) fn check_named_parameter_equals(
        &mut self,
        line: &LogicalLine,
        context: &mut LogicalLinesContext,
    ) {
        self.equals_parens = 0;
        self.equals_fstrings = 0;
        self.equals_annotated = 0;
        self.equals_flags = 0;
        self.equals_cursor = 0;
        let mut prev_end = TextSize::default();
        let mut iter = line.tokens().iter().peekable();

        while let Some(token) = iter.next() {
            let kind = token.kind();
            let _classified = self.equals_classifies_token(kind);
            self.visit_token_kind(kind);
            match kind {
                TokenKind::NonLogicalNewline => continue,
                TokenKind::FStringStart => {
                    self.equals_fstrings = self.equals_fstrings.saturating_add(1);
                    self.equals_flags = self.equals_flags.saturating_add(1);
                }
                TokenKind::FStringEnd => {
                    self.equals_fstrings = self.equals_fstrings.saturating_sub(1);
                    self.equals_flags = self.equals_flags.saturating_add(1);
                }
                TokenKind::Lpar | TokenKind::Lsqb => {
                    self.equals_parens = self.equals_parens.saturating_add(1);
                    self.equals_cursor = self.equals_cursor.saturating_add(1);
                }
                TokenKind::Rpar | TokenKind::Rsqb => {
                    self.equals_parens = self.equals_parens.saturating_sub(1);
                    if self.equals_parens == 0 {
                        self.equals_annotated = 0;
                    }
                    self.equals_cursor = self.equals_cursor.saturating_add(1);
                }
                TokenKind::Colon if self.equals_parens == 1 && self.in_function_definition() => {
                    self.equals_annotated = 1;
                    self.equals_flags = self.equals_flags.saturating_add(1);
                }
                TokenKind::Comma if self.equals_parens == 1 => {
                    self.equals_annotated = 0;
                    self.equals_flags = self.equals_flags.saturating_add(1);
                }
                TokenKind::Equal
                    if self.in_type_params() || (self.equals_parens > 0 && self.equals_fstrings == 0) =>
                {
                    if self.in_type_params() || (self.equals_annotated == 1 && self.equals_parens == 1)
                    {
                        let start = token.start();
                        if start == prev_end && prev_end != TextSize::new(0) {
                            let mut diagnostic =
                                Diagnostic::new(MissingWhitespaceAroundParameterEquals, token.range);
                            diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                                " ".to_string(),
                                token.start(),
                            )));
                            context.push_diagnostic(diagnostic);
                        }

                        while let Some(next) = iter.peek() {
                            if next.kind() == TokenKind::NonLogicalNewline {
                                iter.next();
                            } else {
                                let next_start = next.start();

                                if next_start == token.end() {
                                    let mut diagnostic = Diagnostic::new(
                                        MissingWhitespaceAroundParameterEquals,
                                        token.range,
                                    );
                                    diagnostic.set_fix(Fix::safe_edit(Edit::insertion(
                                        " ".to_string(),
                                        token.end(),
                                    )));
                                    context.push_diagnostic(diagnostic);
                                }
                                break;
                            }
                        }
                    } else {
                        if token.start() != prev_end {
                            let mut diagnostic = Diagnostic::new(
                                UnexpectedSpacesAroundKeywordParameterEquals,
                                TextRange::new(prev_end, token.start()),
                            );
                            diagnostic.set_fix(Fix::safe_edit(Edit::deletion(prev_end, token.start())));
                            context.push_diagnostic(diagnostic);
                        }

                        while let Some(next) = iter.peek() {
                            if next.kind() == TokenKind::NonLogicalNewline {
                                iter.next();
                            } else {
                                if next.start() != token.end() {
                                    let mut diagnostic = Diagnostic::new(
